/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --an-select-height | --an-select-bg | --an-select-fg | --an-select-border-color
   | --an-select-radius | --an-select-font-size | --an-select-padding-x | --an-select-focus-ring.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  display: inline-block;
  vertical-align: middle;
  color-scheme: light dark;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

/* The light-DOM <option> list feeds the inner <select>; it must never paint. */
::slotted(option) {
  display: none !important;
}

.base {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  font-family: inherit;
}

.label {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  color: var(--an-color-fg-1, #18181b);
  font-size: var(--an-font-size-sm, 0.875rem);
  line-height: 1.4;
}

.control {
  position: relative;
  display: block;
}

.select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: var(--an-select-height, var(--an-space-9, 2.25rem));
  padding: 0 calc(var(--an-select-padding-x, var(--an-space-3, 0.75rem)) + 1.25rem) 0
    var(--an-select-padding-x, var(--an-space-3, 0.75rem));
  border: 1px solid var(--an-select-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-select-radius, var(--an-radius-md, 0.5rem));
  background: var(--an-select-bg, var(--an-color-bg-1, #ffffff));
  color: var(--an-select-fg, var(--an-color-fg-1, #18181b));
  font-family: inherit;
  font-size: var(--an-select-font-size, var(--an-font-size-sm, 0.875rem));
  line-height: 1.4;
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
}

.select:focus-visible {
  outline: 2px solid var(--an-select-focus-ring, var(--an-color-accent-9, #2563eb));
  outline-offset: 1px;
  border-color: var(--an-select-focus-ring, var(--an-color-accent-9, #2563eb));
}

.select:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.select[aria-invalid='true'] {
  border-color: var(--an-color-danger-9, #dc2626);
}

/* Self-drawn arrow: a border triangle, so no image asset is needed. */
.chevron {
  position: absolute;
  top: 50%;
  right: var(--an-select-padding-x, var(--an-space-3, 0.75rem));
  width: 0;
  height: 0;
  margin-top: -0.175rem;
  border-left: 0.3rem solid transparent;
  border-right: 0.3rem solid transparent;
  border-top: 0.35rem solid var(--an-select-fg, var(--an-color-fg-1, #18181b));
  opacity: 0.6;
  pointer-events: none;
}

:host([size='sm']) .select {
  height: var(--an-select-height, var(--an-space-8, 2rem));
  padding: 0 calc(var(--an-select-padding-x, var(--an-space-2, 0.5rem)) + 1rem) 0
    var(--an-select-padding-x, var(--an-space-2, 0.5rem));
  border-radius: var(--an-select-radius, var(--an-radius-sm, 0.375rem));
  font-size: var(--an-select-font-size, var(--an-font-size-xs, 0.8125rem));
}

:host([size='sm']) .chevron {
  right: var(--an-select-padding-x, var(--an-space-2, 0.5rem));
}

:host([size='lg']) .select {
  height: var(--an-select-height, var(--an-space-11, 2.75rem));
  padding: 0 calc(var(--an-select-padding-x, var(--an-space-4, 1rem)) + 1.25rem) 0
    var(--an-select-padding-x, var(--an-space-4, 1rem));
  border-radius: var(--an-select-radius, var(--an-radius-lg, 0.625rem));
  font-size: var(--an-select-font-size, var(--an-font-size-md, 1rem));
}

:host([size='lg']) .chevron {
  right: var(--an-select-padding-x, var(--an-space-4, 1rem));
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return Object.keys(this.defaults).map(toKebabCase);
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

import selectStyles from './an-select.css?inline';
import { AnElement } from '../internal/base';

/** Control sizes of `<an-select>`. */
export type AnSelectSize = 'sm' | 'md' | 'lg';

const SIZES: readonly AnSelectSize[] = ['sm', 'md', 'lg'];

/** Shown to the owning form when `required` is set and nothing is selected. */
const REQUIRED_MESSAGE = '此字段为必填项。';

function oneOf<T extends string>(allowed: readonly T[], value: string, fallback: T): T {
  return (allowed as readonly string[]).includes(value) ? (value as T) : fallback;
}

/** Escapes text used inside an attribute value or element content. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/** One `<option>` mirrored from the light DOM into the shadow `<select>`. */
interface OptionSpec {
  value: string;
  text: string;
  selected: boolean;
  disabled: boolean;
  /** The synthetic `value=""` option rendered from `placeholder`. */
  placeholder: boolean;
}

/**
 * `<an-select>` — a select control backed by a real native `<select>` inside the
 * shadow root. Markup stays native: the author writes `<option>` children in the
 * light DOM and the element mirrors them into the shadow select, so option
 * semantics, keyboard interaction, mobile pickers and screen-reader behaviour
 * all come from the platform.
 *
 * ```html
 * <an-select name="city" label="城市" placeholder="请选择">
 *   <option value="bj">北京</option>
 *   <option value="sh">上海</option>
 * </an-select>
 * ```
 *
 * The light-DOM options are the source of truth and never render on the page
 * (`::slotted(option) { display: none }`). They are re-read on `slotchange` and
 * on light-DOM mutations, so adding, removing or reconfiguring an option at
 * runtime is reflected in the shadow select.
 *
 * The host is a form-associated custom element: the inner select lives across a
 * shadow boundary and is therefore not part of the outer `<form>`, so the host
 * registers its own entry instead (`ElementInternals.setFormValue()` /
 * `setValidity()`), exactly like `<an-input>`.
 *
 * `value` seeds the selection from its attribute but is never written back to
 * it: after mount the property and the inner select own the state.
 * `formResetCallback()` restores the value captured at mount time and
 * `formDisabledCallback()` mirrors a disabled ancestor `<fieldset>`.
 *
 * @attr {string} value - Initial selection. Never reflected back onto the attribute.
 * @attr {string} label - Visible label text; also names the control.
 * @attr {string} placeholder - When non-empty, prepends a disabled `value=""` option.
 * @attr {('sm'|'md'|'lg')} size - Control size. Default: "md".
 * @attr {boolean} disabled - Disables the inner select and bars validation.
 * @attr {boolean} required - Raises `valueMissing` while the value is empty.
 * @attr {boolean} invalid - Marks the control invalid with `aria-invalid="true"`.
 * @attr {string} name - Form field name used by `FormData`.
 *
 * @fires an-select-change - The user picked another option; `detail = { value, originalEvent }`.
 *
 * @csspart base - The wrapper around the control.
 * @csspart label - The visible `<label>`; rendered only when `label` is non-empty.
 * @csspart select - The internal native `<select>` element.
 * @csspart chevron - The decorative arrow drawn over the select.
 *
 * @cssprop --an-select-height - Control height; defaults to 2.25rem (2rem sm, 2.75rem lg).
 * @cssprop --an-select-bg - Control background; defaults to the `bg-1` token.
 * @cssprop --an-select-fg - Text and arrow colour; defaults to the `fg-1` token.
 * @cssprop --an-select-border-color - Border colour; defaults to the `border-1` token.
 * @cssprop --an-select-radius - Border radius; defaults to the `radius-md` token.
 * @cssprop --an-select-font-size - Text size; defaults to the `font-size-sm` token.
 * @cssprop --an-select-padding-x - Horizontal padding; defaults to the `space-3` token.
 * @cssprop --an-select-focus-ring - Focus outline colour; defaults to the `accent-9` token.
 */
export class AnSelect extends AnElement {
  static override styles: string = selectStyles;

  /** Opts the host into form participation so its value reaches the outer form. */
  static override formAssociated = true;

  /**
   * `value` is deliberately not part of `defaults`: the base class reflects
   * every default property back onto its attribute, while this component must
   * never write `value` back. It is observed and exposed manually below.
   */
  static override defaults = {
    label: '',
    placeholder: '',
    size: 'md',
    disabled: false,
    required: false,
    invalid: false,
    name: '',
  };

  declare label: string;
  declare placeholder: string;
  declare size: AnSelectSize;
  declare disabled: boolean;
  declare required: boolean;
  declare invalid: boolean;
  declare name: string;

  #value = '';
  /** Reset target, captured on the first sync that can describe the selection. */
  #initialValue = '';
  #initialCaptured = false;
  /**
   * True once the value is authoritative and must be re-applied on every
   * rebuild: either markup/property supplied it, or the mount-time default was
   * captured (see `#captureInitialValue`).
   */
  #valueSeeded = false;
  /** Set by `formDisabledCallback` (e.g. a disabled ancestor `<fieldset>`). */
  #formDisabled = false;
  /** Signature of the options mirrored into the shadow select last. */
  #signature = '';
  /** The select node the signature belongs to; a re-render replaces it. */
  #syncedSelect: HTMLSelectElement | null = null;
  #specs: OptionSpec[] = [];
  #observer: MutationObserver | null = null;

  /** `value` and the forwarded ARIA names are observed outside `defaults`. */
  static override get observedAttributes(): string[] {
    return [...super.observedAttributes, 'value', 'aria-label', 'aria-labelledby'];
  }

  constructor() {
    super();
    // Delegation on the shadow root survives the innerHTML re-render.
    this.shadowRoot!.addEventListener('change', this.#onChange);
    this.shadowRoot!.addEventListener('slotchange', this.#onSlotChange);
  }

  /** Current selection. Setting it moves the inner select without re-rendering. */
  get value(): string {
    return this.#value;
  }

  set value(next: string) {
    this.#setValue(next);
  }

  /** The attribute seeds the value; it is never written back by the property. */
  override attributeChangedCallback(
    name: string,
    oldValue: string | null,
    value: string | null,
  ): void {
    if (name === 'value') {
      if (oldValue !== value) this.#setValue(value ?? '');
      return;
    }
    if (name === 'aria-label' || name === 'aria-labelledby') {
      // Forwarded to the inner select only while no visible label exists.
      if (oldValue !== value && !this.label) this.requestUpdate();
      return;
    }
    super.attributeChangedCallback(name, oldValue, value);
  }

  protected render(): string {
    const disabled = this.disabled || this.#formDisabled;
    const attrs =
      ` class="select" part="select"` +
      (disabled ? ' disabled aria-disabled="true"' : '') +
      (this.required ? ' required aria-required="true"' : '') +
      (this.invalid ? ' aria-invalid="true"' : '') +
      (this.label ? '' : this.#forwardedName());
    const select = `<select${attrs}></select>`;
    const control = `<span class="control">${select}<span class="chevron" part="chevron" aria-hidden="true"></span></span>`;
    return this.label
      ? `<div class="base" part="base"><label class="label" part="label"><span class="label-text">${escapeHtml(this.label)}</span>${control}</label><slot></slot></div>`
      : `<div class="base" part="base">${control}<slot></slot></div>`;
  }

  protected override afterRender(): void {
    this.#syncOptions();
    const internals = this.internals;
    if (!internals) return;
    const disabled = this.disabled || this.#formDisabled;
    internals.ariaDisabled = disabled ? 'true' : null;
    internals.ariaRequired = this.required ? 'true' : null;
    internals.ariaInvalid = this.invalid ? 'true' : null;
    this.#syncForm();
  }

  protected override onConnect(): void {
    this.#startObserving();
  }

  protected override onDisconnect(): void {
    this.#observer?.disconnect();
  }

  protected override onFormReset(): void {
    this.#valueSeeded = true;
    this.#value = this.#initialValue;
    this.#applyValue();
  }

  /** Mirrors a platform-level disable (e.g. ancestor `<fieldset disabled>`). */
  protected override onFormDisabled(disabled: boolean): void {
    this.#formDisabled = disabled;
    this.requestUpdate();
  }

  #setValue(next: string | null | undefined): void {
    this.#valueSeeded = true;
    this.#value = next === null || next === undefined ? '' : String(next);
    this.#applyValue();
  }

  /** Reads the light-DOM `<option>` children, placeholder first. */
  #optionSpecs(): OptionSpec[] {
    const specs: OptionSpec[] = [];
    if (this.placeholder) {
      specs.push({
        value: '',
        text: this.placeholder,
        selected: true,
        disabled: true,
        placeholder: true,
      });
    }
    for (const child of Array.from(this.children)) {
      if (child.localName !== 'option') continue;
      const option = child as HTMLOptionElement;
      specs.push({
        value: option.value,
        text: option.textContent ?? '',
        selected: option.selected,
        disabled: option.disabled,
        placeholder: false,
      });
    }
    return specs;
  }

  /**
   * Mirrors the light-DOM options into the shadow select.
   *
   * A signature check keeps this cheap and, more importantly, keeps it from
   * looping: `slotchange` fires once per re-render, and only a real difference
   * in the option list rebuilds the shadow nodes.
   */
  #syncOptions(): void {
    const select = this.#select;
    if (!select) return;
    const specs = this.#optionSpecs();
    const signature = JSON.stringify(specs);
    if (select !== this.#syncedSelect || signature !== this.#signature) {
      this.#signature = signature;
      this.#syncedSelect = select;
      this.#fill(select, specs);
    }
    this.#specs = specs;
    this.#applyValue();
  }

  #fill(select: HTMLSelectElement, specs: readonly OptionSpec[]): void {
    select.innerHTML = '';
    for (const spec of specs) {
      const option = document.createElement('option');
      option.value = spec.value;
      option.textContent = spec.text;
      option.disabled = spec.disabled;
      option.selected = spec.selected;
      if (spec.placeholder) option.className = 'placeholder';
      select.append(option);
    }
  }

  /** The option the platform would pick with no explicit value: last `selected`, else the first. */
  #defaultValue(): string {
    for (let index = this.#specs.length - 1; index >= 0; index -= 1) {
      if (this.#specs[index].selected) return this.#specs[index].value;
    }
    return this.#specs.length > 0 ? this.#specs[0].value : '';
  }

  /**
   * Pushes the stored value into the inner select and adopts the platform's
   * answer, so the property always describes what is actually selected.
   *
   * A parser-created element can connect before its `<option>` children are
   * parsed. An empty select cannot represent a selection, so the echo is only
   * adopted once the option list exists; otherwise a value seeded from markup
   * would be wiped on the first sync.
   */
  #applyValue(): void {
    const select = this.#select;
    if (!select) return;
    if (this.#valueSeeded) {
      select.value = this.#value;
      if (this.#specs.length > 0) this.#value = select.value;
    } else {
      this.#value = this.#defaultValue();
      select.value = this.#value;
    }
    this.#captureInitialValue();
    this.#syncForm();
  }

  /**
   * Remembers the selection the element was mounted with (the reset target).
   *
   * Captured on the first sync that can describe it: either options are present
   * or markup supplied a value. Waiting for the options keeps a parser-created
   * element (children arrive after `connectedCallback`) from pinning `''`.
   *
   * Capturing freezes the value too: from then on a rebuild re-applies what was
   * selected, so removing that option leaves the control empty instead of
   * silently jumping to the new first option.
   */
  #captureInitialValue(): void {
    if (this.#initialCaptured) return;
    if (this.#specs.length === 0 && !this.#valueSeeded) return;
    this.#initialValue = this.#value;
    this.#initialCaptured = true;
    this.#valueSeeded = true;
  }

  /**
   * Publishes the value and the constraint to the owning form.
   *
   * An empty selection contributes no entry (native select parity), and a
   * disabled control is *barred from constraint validation*: it submits nothing
   * and never blocks the outer form, exactly like `<select disabled>`.
   */
  #syncForm(): void {
    const internals = this.internals;
    if (!internals) return;
    const disabled = this.disabled || this.#formDisabled;
    if (disabled) {
      internals.setFormValue(null);
      internals.setValidity({});
      return;
    }
    const value = this.#value;
    internals.setFormValue(value === '' ? null : value);
    if (this.required && value === '') {
      internals.setValidity({ valueMissing: true }, REQUIRED_MESSAGE, this.#select ?? undefined);
    } else {
      internals.setValidity({});
    }
  }

  /** Host `aria-label` / `aria-labelledby`, forwarded while no visible label exists. */
  #forwardedName(): string {
    const label = this.getAttribute('aria-label');
    const labelledby = this.getAttribute('aria-labelledby');
    return (
      (label ? ` aria-label="${escapeHtml(label)}"` : '') +
      (labelledby ? ` aria-labelledby="${escapeHtml(labelledby)}"` : '')
    );
  }

  /** Re-reads the light DOM: options may be added, removed or reconfigured. */
  #startObserving(): void {
    if (typeof MutationObserver === 'undefined') return;
    this.#observer ??= new MutationObserver(() => {
      this.#syncOptions();
    });
    this.#observer.observe(this, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: ['value', 'selected', 'disabled', 'label'],
    });
  }

  #onChange = (event: Event): void => {
    const select = this.#select;
    if (!select || event.target !== select) return;
    if (this.disabled || this.#formDisabled) return;
    this.#value = select.value;
    this.#valueSeeded = true;
    this.#syncForm();
    this.emit('an-select-change', { value: this.#value, originalEvent: event });
  };

  /**
   * The slot is recreated on every render, so this fires on connect too; the
   * signature check in `#syncOptions()` keeps it from re-entering.
   */
  #onSlotChange = (): void => {
    this.#syncOptions();
  };

  /**
   * Platform parity for form-associated custom elements: the host carries no
   * `validationMessage` of its own, so the message the platform computed is read
   * off the internals here — this is what `<an-field>` displays.
   */
  get validationMessage(): string {
    return this.internals?.validationMessage ?? '';
  }

  /** Platform constraint state; `undefined` when the element has no internals. */
  get validity(): ValidityState | undefined {
    return this.internals?.validity;
  }

  get #select(): HTMLSelectElement | null {
    return this.shadowRoot?.querySelector('select') ?? null;
  }
}

export { SIZES };
